import { Options, PlainObject } from './store';
export declare type OmitNever<T> = Pick<T, {
    [P in keyof T]: T[P] extends never ? never : P;
}[keyof T]>;
export declare type PickProps<T> = {
    [P in keyof T]: T[P] extends Function ? never : T[P];
};
export declare type KVProps<T> = Partial<OmitNever<PickProps<T>>>;
export declare type Payload<T> = ((store: T) => KVProps<T>) | KVProps<T>;
export declare type Action<T, U> = {
    type: U;
    payload: Payload<T>;
};
export declare type ActionFn<T, U> = (store: T) => {
    type: U;
    payload: Payload<T>;
};
export declare type PropsAction<K extends keyof T, T> = {
    type: string;
    payload: KVProps<T>;
};
export declare enum Role {
    STORE = "STORE",
    COMPONENT = "COMPONENT"
}
export declare enum CompType {
    FUNCTION = "FUNCTION",
    CLASS = "CLASS"
}
export declare type Lisener = {
    forceUpdate: Function;
    self: any;
    watchedProps: Set<string>;
    compType: CompType;
    role: Role;
};
export declare type Meta = {
    liseners: Lisener[];
    options: Options;
    key: string;
    storeName: string;
    ignoredProps: string[];
    initialValues: PlainObject;
};
